import json, itertools, sys

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
N = 15

# Precompute all valid triples (a,b,c) with a+b==c and distinct numbers
triples = []
for a, b, c in itertools.permutations(L, 3):
    if a + b == c:
        triples.append((a, b, c))

# Use backtracking to select N disjoint triples
used = set()
solution = []

# Sort triples to try smaller ones first for efficiency
triples.sort(key=lambda t: (t[2], t[0], t[1]))

sys.setrecursionlimit(10000)

def backtrack(start):
    if len(solution) == N:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(i + 1):
            return True
        # undo
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)

if found:
    witness = {
        "polarity": "positive",
        "data": {
            "triples": solution
        }
    }
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": None,
        "method": "backtracking"
    }
print("WITNESS: " + json.dumps(witness))
